insert into public.destinations(slug,name,country,region,category,image_fallback,tagline,description,duration,best_time,highlights) values
('bali','Bali','Indonesia','Southeast Asia','Coast','/images/bali.svg','Where the island slows you down.','Ancient temples, lush green valleys and a coastline made for slow mornings. Bali is a place to take a breath and let curiosity lead the way.','7–10 days','April – October',ARRAY['Ubud rice terraces','Uluwatu coast','Local art & culture']),
('swiss-alps','Swiss Alps','Switzerland','Europe','Mountains','/images/alps.svg','Find your altitude.','Quiet alpine villages, mountain trails and impossibly clear lakes. Wander through dramatic peaks and discover a different pace of life.','5–8 days','June – September',ARRAY['Alpine hiking trails','Mountain train journeys','Lakeside villages']),
('marrakech','Marrakech','Morocco','North Africa','Culture','/images/marrakech.svg','A city of color and contrast.','Winding medina streets, fragrant gardens and warm ochre architecture. Discover the stories, design and energy of the Red City.','3–5 days','March – May',ARRAY['Historic medina','Majorelle Garden','Atlas mountain day trips']),
('kyoto','Kyoto','Japan','East Asia','Culture','/images/kyoto.svg','Tradition in every detail.','Lantern-lit lanes, quiet shrines and timeless gardens. Kyoto invites you to see the beauty in the small, everyday moments.','4–6 days','March – May',ARRAY['Temple walks','Arashiyama bamboo grove','Traditional neighborhoods']),
('amalfi','Amalfi Coast','Italy','Europe','Coast','/images/amalfi.svg','Chase the Mediterranean light.','Sunlit villages tucked into cliffs, lemon groves and endlessly blue water. Slow down and linger a little longer along the coast.','4–7 days','May – September',ARRAY['Positano viewpoints','Coastal boat rides','Local seaside dining']),
('patagonia','Patagonia','Argentina & Chile','South America','Nature','/images/patagonia.svg','For the beautifully untamed.','Wild landscapes, glacier-fed lakes and windswept mountain paths. Head south for an adventure that feels far from the ordinary.','8–12 days','November – March',ARRAY['National park trails','Glacier viewpoints','Dramatic mountain scenery'])
